# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Timekeeping reservation persistence across companies" do
  include_context "timekeeping entry writes"

  it "answers another company's prepare with the same operation id as its own new operation and leaves the first company's committed reservation alone" do
    arrange = timekeeping_arrange
    company_a = arrange.company
    company_b = arrange.company
    operations = %w[prepare commit abort mark_billed detach_entries]
    service_a = arrange.service_identity(company: company_a, name: "invoice-boundary", operations:)
    service_b = arrange.service_identity(company: company_b, name: "invoice-boundary", operations:)
    entry_a = arrange.entry(company: company_a, user: arrange.user(company: company_a, role: "employee"),
                            project: arrange.project(company: company_a))
    entry_b = arrange.entry(company: company_b, user: arrange.user(company: company_b, role: "employee"),
                            project: arrange.project(company: company_b))
    operation_id = SecureRandom.uuid
    send_command = lambda do |company, token, route, body|
      post "/v1/companies/#{company}/reservations/#{route}",
           params: JSON.generate({ "generation" => arrange.current_generation }.merge(body)),
           headers: { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json" }
      response
    end

    send_command.call(company_a, service_a, "prepare",
                      { "invoice_id" => 501, "operation_id" => operation_id, "disposition" => "active", "entries" => [entry_a] })
    send_command.call(company_a, service_a, "commit", { "invoice_id" => 501, "operation_id" => operation_id })
    expect(arrange.reservations_for(entry_a)).to eq([{ "invoice_id" => 501, "state" => "committed" }])

    # "Operation ids are unique only within a company."
    other = send_command.call(company_b, service_b, "prepare",
                              { "invoice_id" => 501, "operation_id" => operation_id, "disposition" => "active", "entries" => [entry_b] })

    expect(other.status).to eq(200)
    expect(other.parsed_body).to eq(
      "operation_id" => operation_id, "state" => "prepared",
      "entries" => [{ "entry_id" => entry_b, "company_id" => company_b }]
    )
    expect(arrange.reservations_for(entry_b)).to eq([{ "invoice_id" => 501, "state" => "provisional" }])
    expect(arrange.reservations_for(entry_a)).to eq([{ "invoice_id" => 501, "state" => "committed" }])
  end
end

RSpec.describe "Timekeeping reservation abort persistence" do
  include_context "timekeeping entry writes"

  it "writes one audit row and one unlocked outbox snapshot when an abort drops a provisional reservation, and a replayed abort writes nothing" do
    arrange = timekeeping_arrange
    company = arrange.company
    service = arrange.service_identity(company:, name: "invoice-boundary",
                                       operations: %w[prepare commit abort mark_billed detach_entries])
    entry_id = arrange.entry(company:, user: arrange.user(company:, role: "employee"), project: arrange.project(company:))
    operation_id = SecureRandom.uuid
    send_command = lambda do |route, body|
      post "/v1/companies/#{company}/reservations/#{route}",
           params: JSON.generate({ "generation" => arrange.current_generation }.merge(body)),
           headers: { "Authorization" => "Bearer #{service}", "Content-Type" => "application/json" }
      response
    end
    send_command.call("prepare", { "invoice_id" => 501, "operation_id" => operation_id, "disposition" => "active",
                                   "entries" => [entry_id] })
    expect(arrange.entry_locked(entry_id)).to be(true)
    audits_before = AuditEvent.where(entry_id:).count
    snapshots_before = OutboxSnapshot.where(id: entry_id).count
    version_before = Entry.find(entry_id).version

    # "Every reservation change that flips `locked`, every mark-billed and every detach writes an audit row and an
    # outbox snapshot row in the same transaction as the change."
    aborted = send_command.call("abort", { "invoice_id" => 501, "operation_id" => operation_id })

    expect(aborted.parsed_body).to eq("dropped" => 1)
    expect(arrange.entry_locked(entry_id)).to be(false)
    expect(AuditEvent.where(entry_id:).count).to eq(audits_before + 1)
    expect(OutboxSnapshot.where(id: entry_id).count).to eq(snapshots_before + 1)
    latest = OutboxSnapshot.where(id: entry_id).order(:outbox_position).last
    expect(latest.locked).to be(false)
    expect(latest.version).to eq(Entry.find(entry_id).version)
    expect(Entry.find(entry_id).version).to eq(version_before + 1)

    # "A replay after a terminal state changes nothing."
    replay = send_command.call("abort", { "invoice_id" => 501, "operation_id" => operation_id })

    expect(replay.parsed_body).to eq(aborted.parsed_body)
    expect(AuditEvent.where(entry_id:).count).to eq(audits_before + 1)
    expect(OutboxSnapshot.where(id: entry_id).count).to eq(snapshots_before + 1)
    expect(Entry.find(entry_id).version).to eq(version_before + 1)
  end
end

RSpec.describe "Timekeeping entry locked flag after reservation changes" do
  include_context "timekeeping entry writes"

  it "reports locked through the entry API exactly while a reservation exists across prepare, commit and a releasing commit" do
    arrange = timekeeping_arrange
    company = arrange.company
    service = arrange.service_identity(company:, name: "invoice-boundary",
                                       operations: %w[prepare commit abort mark_billed detach_entries])
    owner_token = arrange.token_for(arrange.user(company:, role: "owner"))
    entry_id = arrange.entry(company:, user: arrange.user(company:, role: "employee"), project: arrange.project(company:))
    send_command = lambda do |route, body|
      post "/v1/companies/#{company}/reservations/#{route}",
           params: JSON.generate({ "generation" => arrange.current_generation }.merge(body)),
           headers: { "Authorization" => "Bearer #{service}", "Content-Type" => "application/json" }
      response
    end
    locked_via_api = lambda do
      get "/v1/companies/#{company}/entries/#{entry_id}", headers: { "Authorization" => "Bearer #{owner_token}" }
      expect(response).to have_http_status(:ok)
      response.parsed_body.fetch("locked")
    end
    first = SecureRandom.uuid
    second = SecureRandom.uuid

    # "From here on the entry API reports `locked: true` exactly when the entry has a reservation."
    expect(locked_via_api.call).to be(false)
    send_command.call("prepare", { "invoice_id" => 501, "operation_id" => first, "disposition" => "active", "entries" => [entry_id] })
    expect(locked_via_api.call).to be(true)
    send_command.call("commit", { "invoice_id" => 501, "operation_id" => first })
    expect(locked_via_api.call).to be(true)
    send_command.call("prepare", { "invoice_id" => 501, "operation_id" => second, "disposition" => "active", "entries" => [] })
    expect(locked_via_api.call).to be(true)
    released = send_command.call("commit", { "invoice_id" => 501, "operation_id" => second })
    expect(released.parsed_body).to eq("reserved" => 0, "released" => 1)
    expect(locked_via_api.call).to be(false)
  end
end
